const ticketResponse = $('Get Ticket Snapshot').first().json;
const ticket = ticketResponse && ticketResponse.ticket;
if (!ticket || !ticket.id) { throw new Error('Ticket snapshot missing or malformed'); }
const pages = $input.all().map(item => item.json).filter(body => body && Array.isArray(body.comments));
if (pages.length === 0) { throw new Error('No comment pages fetched'); }
const lastPage = pages[pages.length - 1];
if (lastPage.next_page !== null && lastPage.next_page !== undefined) { throw new Error('Comment pagination incomplete: next_page still present'); }
const comments = pages.flatMap(body => body.comments);
if (typeof ticket.comment_count === 'number' && comments.length < ticket.comment_count) { throw new Error('Comment pagination incomplete: got ' + comments.length + ', expected ' + ticket.comment_count); }
return [{ json: { ticket, comments } }];

// sandbox-safe SHA-256: the JS task runner exposes no `crypto` global
// (verified against node:crypto on 2026-10-13 before deployment).
function sha256Hex(input) {
  if (typeof input !== 'string') { throw new Error('sha256: string input required'); }
  const enc = [];
  for (let i = 0; i < input.length; i++) {
    let c = input.codePointAt(i);
    if (c > 0xffff) i++;
    if (c < 0x80) enc.push(c);
    else if (c < 0x800) enc.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) enc.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else enc.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  const bytes = Uint8Array.from(enc);
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = bytes.length;
  const bitLenHi = Math.floor(l / 0x20000000);
  const bitLenLo = (l << 3) >>> 0;
  const withOne = l + 1;
  const totalLen = ((withOne + 63) >> 6) << 6;
  const m = new Uint8Array(totalLen);
  m.set(bytes);
  m[l] = 0x80;
  const dv = new DataView(m.buffer);
  dv.setUint32(totalLen - 8, bitLenHi);
  dv.setUint32(totalLen - 4, bitLenLo);
  const w = new Int32Array(64);
  const rr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < totalLen; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = dv.getInt32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = rr(w[i-15],7) ^ rr(w[i-15],18) ^ (w[i-15] >>> 3);
      const s1 = rr(w[i-2],17) ^ rr(w[i-2],19) ^ (w[i-2] >>> 10);
      w[i] = (w[i-16] + s0 + w[i-7] + s1) | 0;
    }
    let [a,b,c,d,e,f,g,h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rr(e,6) ^ rr(e,11) ^ rr(e,25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) | 0;
      const S0 = rr(a,2) ^ rr(a,13) ^ rr(a,22);
      const mj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + mj) | 0;
      h=g; g=f; f=e; e=(d+t1)|0; d=c; c=b; b=a; a=(t1+t2)|0;
    }
    H[0]=(H[0]+a)|0; H[1]=(H[1]+b)|0; H[2]=(H[2]+c)|0; H[3]=(H[3]+d)|0;
    H[4]=(H[4]+e)|0; H[5]=(H[5]+f)|0; H[6]=(H[6]+g)|0; H[7]=(H[7]+h)|0;
  }
    return H.map(x => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

// Stage 2 source-only (p2-194): build a knowledge-source-v1 snapshot.
// Option A contract: idempotent identity = source_type + source_id +
// source_updated_at; snapshot_hash travels in references as evidence.
const source = $input.first().json;
const ticket = source.ticket;
const comments = source.comments;
if (!ticket || !ticket.id) { throw new Error('snapshot build: ticket missing'); }
if (!Array.isArray(comments)) { throw new Error('snapshot build: comments missing'); }
const payload = {
  ticket: ticket,
  comments: comments,
  comment_count: comments.length,
  pagination_complete: true,
};
const canonical = JSON.stringify(payload);
const snapshot_hash = sha256Hex(canonical);
return [{ json: {
  schema_version: 'knowledge-source-v1',
  source_type: 'zendesk_ticket',
  source_id: String(ticket.id),
  source_updated_at: String(ticket.updated_at || ticket.created_at || ''),
  payload: payload,
  references: {
    snapshot_hash: snapshot_hash,
    snapshot_builder: 'n8n-solved-source-only',
    captured_fields: 'ticket,comments'
  }
}}];

// Stage 2 source-only (p2-194): three-state receipt gate. Only accepted /
// already_exists / stale_ignored with a non-empty task_id pass; anything else
// throws so the workflow error path (ops alert) fires.
const body = $input.first().json;
const status = body ? body.status : null;
const taskId = body ? body.task_id : null;
const allowed = ['accepted', 'already_exists', 'stale_ignored'];
if (!allowed.includes(status)) {
  throw new Error('receipt check: unexpected status ' + JSON.stringify(status));
}
if (!taskId || !String(taskId).trim()) {
  throw new Error('receipt check: empty task_id');
}
return [{ json: { delivered: true, status: String(status), task_id: String(taskId) } }];
